11	func ParseHeartbeatLine(raw string) (id string, status string, version string, tags []string, err error) { //nolint:revive // TODO
12		parts := strings.Split(raw, "|")
13		if len(parts) < 3 {
14			return "", "", "", nil, fmt.Errorf("bad heartbeat %q", raw)
15		}
16		id = strings.TrimSpace(parts[0])
17		if id == "" || len(id) > 64 {
18			return "", "", "", nil, fmt.Errorf("bad id %q", id)
19		}
20		status = strings.ToUpper(strings.TrimSpace(parts[1]))
21		if !models.IsValidStatus(status) {
22			return id, "", "", nil, fmt.Errorf("unknown status %q", status)
23		}
24		version = strings.TrimSpace(parts[2])
25		if len(parts) > 3 {
26			tags = normalizeTags(strings.Split(parts[3], ","))
27		}
28		return id, status, version, tags, nil
29	}
