8	const maxTenantLen = 32
9	
10	// Tenant identifies the owner of a device fleet. A Tenant can only be
11	// obtained through ParseTenant, so every value in circulation is already
12	// non-empty, lowercase, and at most 32 characters long; nothing downstream
13	// needs to check it again.
14	type Tenant struct {
15		id string
16	}
17	
18	// ParseTenant validates a raw tenant identifier once, at the boundary.
19	func ParseTenant(raw string) (Tenant, error) {
20		if raw == "" {
21			return Tenant{}, errors.New("tenant: empty")
22		}
23		if len(raw) > maxTenantLen {
24			return Tenant{}, fmt.Errorf("tenant %q: longer than %d characters", raw, maxTenantLen)
25		}
26		for _, r := range raw {
27			if !isTenantRune(r) {
28				return Tenant{}, fmt.Errorf("tenant %q: want lowercase letters, digits, or '-'", raw)
29			}
30		}
31		return Tenant{id: raw}, nil
32	}
33	
34	// ID returns the validated identifier for use in storage keys and logs.
35	func (t Tenant) ID() string {
36		return t.id
37	}
38	
39	func isTenantRune(r rune) bool {
40		return (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-'
41	}
