258	// MarkDown marks a device as down.
259	func (s *DeviceService) MarkDown(ctx context.Context, tenant, id, reason string) error {
260		d, err := s.getOrCreate(ctx, tenant, id)
261		if err != nil {
262			return err
263		}
264		if d.Status == models.StatusDown {
265			return nil
266		}
267		d.Status = models.StatusDown
268		d.LastSeen = time.Now()
269		if err := s.repo.Save(ctx, d); err != nil {
270			return fmt.Errorf("mark down %s: %w", id, err)
271		}
272		s.mu.Lock()
273		s.cache[cacheKey(tenant, id)] = d
274		s.mu.Unlock()
275		s.audit.Write("marked down " + id + ": " + reason) //nolint:errcheck // TODO
276		return s.notifier.Send("ops", "device "+id+" marked down: "+reason)
277	}
