20	// AuditLog is a log for audits.
21	type AuditLog struct {
22		mu sync.Mutex
23		w  io.Writer
24		n  int
25	}
26	
27	// NewAuditLog creates a new AuditLog.
28	func NewAuditLog(w io.Writer) *AuditLog {
29		return &AuditLog{w: w}
30	}
31	
32	// Write writes a message to the audit log.
33	func (a *AuditLog) Write(msg string) error {
34		if a == nil || a.w == nil {
35			return nil
36		}
37		a.mu.Lock()
38		defer a.mu.Unlock()
39		a.n++
40		stamp := time.Now().UTC().Format(time.RFC3339)
41		if _, err := fmt.Fprintf(a.w, "%s audit: %s\n", stamp, msg); err != nil {
42			return fmt.Errorf("audit: %w", err)
43		}
44		return nil
45	}
46	
47	// Count returns how many entries have been written.
48	func (a *AuditLog) Count() int {
49		if a == nil {
50			return 0
51		}
52		a.mu.Lock()
53		defer a.mu.Unlock()
54		return a.n
55	}
