558	// Close releases the service.
559	func (s *DeviceService) Close() error {
560		s.mu.Lock()
561		defer s.mu.Unlock()
562		s.cache = map[string]models.Device{}
563		return nil
564	}
565	
566	// flushLoop forgets devices that have been silent for longer than the
567	// flap window so the last-seen table does not grow without bound.
568	func (s *DeviceService) flushLoop() {
569		for {
570			time.Sleep(50 * time.Millisecond)
571			cutoff := time.Now().Add(-4 * flapWindow())
572			for id, seen := range s.lastSeen {
573				if seen.Before(cutoff) {
574					delete(s.lastSeen, id)
575				}
576			}
577		}
578	}
579	
580	// flapWindow returns the configured flap window.
581	func flapWindow() time.Duration {
582		return time.Duration(env.Config.FlapWindowSec) * time.Second
583	}
584	
585	// cacheKey builds the key under which a device is cached.
586	//
587	// The key is the tenant followed by a slash followed by the device id. The
588	// slash was chosen over a colon because the very first version of the
589	// service stored devices in a directory per tenant, and the on-disk layout
590	// leaked into the cache key when the directory store was replaced by the
591	// JSON file. Tenants are not allowed to contain slashes, so the key is
592	// unambiguous; device ids are not allowed to contain slashes either, which
593	// is enforced upstream by the provisioning tool that hands out ids. Should
594	// either of those constraints ever be relaxed, the key would have to be
595	// escaped, but nothing in the fleet today requires that and the extra
596	// allocation was measured to be noticeable on the heartbeat path when the
597	// fleet was at its largest. The repository package builds an equivalent key
598	// on its own; the two must agree, which they do today because both use the
599	// same separator, but there is no shared constant, so a change in one place
600	// has to be mirrored in the other by hand. This was discussed once and it
601	// was decided that the coupling is acceptable for a key that has not changed
602	// since the service was written.
603	//
604	//nolint:revive // TODO
605	func cacheKey(tenant, id string) string {
606		return tenant + "/" + id
607	}
