 example

### Before — unowned goroutine, no exit path

```go
func StartWorker(workChan <-chan Work) {
    go func() {
        for {
            work := <-workChan
            process(work)
            // No way to exit this goroutine — it

 outlives every caller.
        }
    }()
}
```

Three defects: the goroutine loops forever (leak), nobody holds a handle to stop or

wait for it (fire-and-forget), and cancellation cannot reach it (no `ctx`).

### After — owned, cancellable, joinable

```go
type Worker struct {
    done chan struct{}
}

func StartWorker(ctx context.Context, workChan <-chan Work) *Worker {
    w := &Worker{done: make(chan struct{})}
    go func() {
        defer close(w.done)
        for {
            select {
            case work, ok := <-workChan:
                if !ok

{
                   return // channel closed — exit, don't spin on zero values
               }
               process(work)
           case <-ctx.Done():
               return // clean exit — cancellation reaches the loop
           }
       }

    }()
    return w
}

func (w *Worker) Wait() { <-w.done }
```

### Second case — uncancellable backoff + unguarded shared write

```go
// ❌ Before
for attempt := 0; attempt < 3; attempt

++ {
    resp, err := http.Post(d.endpoint+"/deploy", "application/json", bytes.NewReader(raw))
    if err != nil {
        time.Sleep(time.Duration(attempt+1) * time.Second) // canc

elled caller waits anyway
        continue
    }
    GlobalRegistry[name] = version // fatal crash if two Deploys race
}

// ✅ After — backoff selects on ctx; state owned by one

 guarded type
for attempt := 0; attempt < 3; attempt++ {
    resp, err := d.post(ctx, raw)
    if err != nil {
        if err := sleepCtx(ctx, backoff(attempt)); err != nil {
            return

 err
        }
        continue
    }
    d.registry.Record(name, version)
}

func sleepCtx(ctx context.Context, d time.Duration) error {
    select {
    case <-time.After(d):
        return nil
    case <-ctx.Done():

        return ctx.Err()
    }
}
```

## Design guidance

- **Whoever starts a goroutine owns its shutdown.** Starting a goroutine is
  acquiring a resource: the constructor/function that spawns it must hand back a way

